export function getGameDom(root = document) {
  return {
    scoreboard: root.querySelector("#scoreboard"),
    round: root.querySelector("#round-number"),
    phase: root.querySelector("#phase-label"),
    latency: root.querySelector("#latency-status"),
    legend: root.querySelector("#legend"),
    instruction: root.querySelector("#map-instruction"),
    map: root.querySelector("#war-map"),
    mapLoading: root.querySelector("#map-loading"),
    territoryLayer: root.querySelector("#territory-layer"),
    mountainLayer: root.querySelector("#mountain-layer"),
    riverLayer: root.querySelector("#river-layer"),
    fleetLayer: root.querySelector("#fleet-layer"),
    battlefieldClip: root.querySelector("#battlefield-clip"),
    labelLayer: root.querySelector("#label-layer"),
    orderLines: root.querySelector("#order-lines"),
    battleAnimationLayer: root.querySelector("#battle-animation-layer"),
    dragLayer: root.querySelector("#drag-layer"),
    playbackStatus: root.querySelector("#playback-status"),
    summary: root.querySelector("#selection-summary"),
    orderModeSwitch: root.querySelector("#order-mode-switch"),
    orderCount: root.querySelector("#order-count"),
    orderList: root.querySelector("#order-list"),
    endTurn: root.querySelector("#end-turn"),
    rollback: root.querySelector("#rollback-turn"),
    pauseGame: root.querySelector("#pause-game"),
    syncNote: root.querySelector("#sync-note"),
    rulesButton: root.querySelector("#rules-button"),
    factionDialog: root.querySelector("#faction-dialog"),
    factionOptions: root.querySelector("#faction-options"),
    modeOptions: root.querySelector("#mode-options"),
    factionIntro: root.querySelector("#faction-intro"),
    rulesDialog: root.querySelector("#rules-dialog"),
    playbackDialog: root.querySelector("#playback-dialog"),
    reportDialog: root.querySelector("#report-dialog"),
    reportTitle: root.querySelector("#report-title"),
    reportList: root.querySelector("#report-list"),
    resultDialog: root.querySelector("#result-dialog"),
    resultSeal: root.querySelector("#result-seal"),
    resultTitle: root.querySelector("#result-title"),
    resultCopy: root.querySelector("#result-copy"),
    resultRollback: root.querySelector("#result-rollback"),
    restart: root.querySelector("#restart-game"),
    zoomIn: root.querySelector("#zoom-in"),
    zoomOut: root.querySelector("#zoom-out"),
    zoomReset: root.querySelector("#zoom-reset"),
  };
}

export function closeAllDialogs(root = document) {
  root.querySelectorAll("dialog[open]").forEach((dialog) => dialog.close());
}
